#include <cstdint>
#include <vector>
#include <string>
#include <fstream>
#include <filesystem>
#include <algorithm>
#include <stdexcept>
#include <cstdio>
using U=uint64_t;namespace fs=std::filesystem;
void save(const fs::path&p,const std::vector<U>&x){std::ofstream f(p,std::ios::binary);f.write((char*)x.data(),x.size()*8);if(!f)throw std::runtime_error(p.string());}
std::vector<U> encode(const std::vector<U>&input,int dim){size_t n=input.size(),init=1+(n+63)/64;std::vector<U>ans(init,0),payload;for(size_t base=0;base<n;base+=1024){U delta[1024]={},trans[1024]={},edge[1024]={};for(size_t i=0;i<1024&&base+i<n;i++)delta[i]=input[base+i]-(i>=size_t(dim)?input[base+i-dim]:U(0));for(int group=0;group<16;group++)for(int bit=0;bit<64;bit++){U column=0;for(int word=0;word<64;word++)column|=((delta[group*64+word]>>bit)&1)<<word;trans[group*64+bit]=column;}for(int i=0;i<1024;i++)edge[i]=trans[i]-(i?trans[i-1]:U(0));for(size_t group=0;group<16&&base+group*64<n;group++){U mask=0;for(int bit=0;bit<64;bit++)mask|=U(edge[group*64+bit]!=0)<<bit;ans[1+base/64+group]=mask;}for(int i=0;i<1024;i++)if(edge[i])payload.push_back(edge[i]);}ans.insert(ans.end(),payload.begin(),payload.end());ans[0]=(U(ans.size())<<32)+0x43504cffULL+U(dim);return ans;}
std::vector<U> decode(const std::vector<U>&data,size_t n,int dim,size_t&consumed){size_t cursor=1+(n+63)/64;std::vector<U>ans(n);for(size_t base=0;base<n;base+=1024){U trans[1024]={},delta[1024]={},sum=0;for(int i=0;i<1024;i++){U e=0;if(base+size_t(i)<((n+63)/64)*64&&((data[1+(base+i)/64]>>(i%64))&1)){if(cursor>=data.size())throw std::runtime_error("decoderbounds");e=data[cursor++];}sum+=e;trans[i]=sum;}for(int group=0;group<16;group++)for(int word=0;word<64;word++){U v=0;for(int bit=0;bit<64;bit++)v|=((trans[group*64+bit]>>word)&1)<<bit;delta[group*64+word]=v;}for(size_t i=0;i<1024&&base+i<n;i++)ans[base+i]=delta[i]+(i>=size_t(dim)?ans[base+i-dim]:U(0));}consumed=cursor;return ans;}
std::vector<U>randomwords(size_t n){std::vector<U>x(n);U s=0x8f39c7324d895f9bULL;for(auto&v:x){s^=s<<13;s^=s>>7;s^=s<<17;v=s;}return x;}
void casewrite(const std::string&set,int index,const std::vector<U>&input,int dim,bool corrected,std::ofstream&cases){size_t n=input.size(),cap=(corrected?((n+1023)/1024)*1024:n)+1+(n+63)/64;auto encoded=encode(input,dim);size_t consumed=0;auto output=decode(encoded,n,dim,consumed);if(output!=input)throw std::runtime_error("independentroundtrip");if(encoded.size()>cap)throw std::runtime_error("capacity");size_t used=encoded.size();encoded.resize(cap,0);fs::path dir=fs::path("fixtures")/set/("case"+std::to_string(index));fs::create_directories(dir);save(dir/"input_u64.bin",input);save(dir/"encoded_u64.bin",encoded);auto decoderinput=encoded;decoderinput[0]=(U(n)<<32)+0x43504cffULL+U(dim);save(dir/"decoder_input_u64.bin",decoderinput);save(dir/"decoded_u64.bin",output);std::vector<U>offs(80,U(-1)); // store160Int32packed in80UInt64, exactlogicalindices below
std::vector<int32_t>co(160,-1),doo(160,-1);size_t next=((n+1023)/1024)%160;co[next]=used;doo[next]=consumed;std::ofstream(dir/"offset_comp_i32.bin",std::ios::binary).write((char*)co.data(),640);std::ofstream(dir/"offset_dec_i32.bin",std::ios::binary).write((char*)doo.data(),640);cases<<index<<" "<<n<<" "<<dim<<" "<<cap<<" "<<used<<" "<<consumed<<"\n";}
int main(int argc,char**argv){if(argc!=2)throw std::runtime_error("originaltracepath");std::ifstream f(argv[1],std::ios::binary);std::vector<U>real(1048576);f.read((char*)real.data(),real.size()*8);if(!f)throw std::runtime_error("shortoriginaltrace");std::ofstream p("cases_primary.txt"),s("cases_partial_corrected.txt");casewrite("primary",0,real,1,false,p);for(int dim=1;dim<=32;dim++)casewrite("primary",dim,randomwords(1024),dim,false,p);int idx=0;for(int n:{1,63,64,65,1023,1025})for(int dim:{1,3,32})casewrite("partial_corrected",idx++,randomwords(n),dim,true,s);printf("CPUindependentbitcodec/decoder:33primarycases18partialcorrectedcases, exactfullroundtrips\n");}
